MutantDict = Annotated[dict[str, Callable], "Mutant"] # type: ignore


def _mutmut_trampoline(orig, mutants, call_args, call_kwargs, self_arg = None): # type: ignore
	"""Forward call to original or mutated function, depending on the environment"""
	import os # type: ignore
	mutant_under_test = os.environ['MUTANT_UNDER_TEST'] # type: ignore
	if mutant_under_test == 'fail': # type: ignore
		from mutmut.__main__ import MutmutProgrammaticFailException # type: ignore
		raise MutmutProgrammaticFailException('Failed programmatically')       # type: ignore
	elif mutant_under_test == 'stats': # type: ignore
		from mutmut.__main__ import record_trampoline_hit # type: ignore
		record_trampoline_hit(orig.__module__ + '.' + orig.__name__) # type: ignore
		# (for class methods, orig is bound and thus does not need the explicit self argument)
		result = orig(*call_args, **call_kwargs) # type: ignore
		return result # type: ignore
	prefix = orig.__module__ + '.' + orig.__name__ + '__mutmut_' # type: ignore
	if not mutant_under_test.startswith(prefix): # type: ignore
		result = orig(*call_args, **call_kwargs) # type: ignore
		return result # type: ignore
	mutant_name = mutant_under_test.rpartition('.')[-1] # type: ignore
	if self_arg is not None: # type: ignore
		# call to a class method where self is not bound
		result = mutants[mutant_name](self_arg, *call_args, **call_kwargs) # type: ignore
	else:
		result = mutants[mutant_name](*call_args, **call_kwargs) # type: ignore
	return result # type: ignore

# Main create function for BioSample/SRA
def create_genbank_submission(organism: str, submission_name: str, submission_dir: str, config_dict: dict[str, Any], metadata: pd.DataFrame, gff_file: Optional[str], table2asn: bool, publication_title: Optional[str], publication_status: Optional[str]):
	args = [organism, submission_name, submission_dir, config_dict, metadata, gff_file, table2asn, publication_title, publication_status]# type: ignore
	kwargs = {}# type: ignore
	return _mutmut_trampoline(x_create_genbank_submission__mutmut_orig, x_create_genbank_submission__mutmut_mutants, args, kwargs, None)

# Main create function for BioSample/SRA
def x_create_genbank_submission__mutmut_orig(organism: str, submission_name: str, submission_dir: str, config_dict: dict[str, Any], metadata: pd.DataFrame, gff_file: Optional[str], table2asn: bool, publication_title: Optional[str], publication_status: Optional[str]):
	create_files(organism=organism, submission_name=submission_name, submission_dir=submission_dir, config_dict=config_dict, metadata=metadata, gff_file=gff_file, publication_title=publication_title, publication_status=publication_status)
	# If using Table2asn do not generate extra genbank files
	if organism not in ["FLU", "COV"] or table2asn:
		create_table2asn(submission_name=submission_name, submission_dir=submission_dir)
		return
	else:
		# If FTP upload for Genbank, create ZIP file for upload if table2asn is set to False
		create_zip(submission_name=submission_name, submission_dir=submission_dir)
	# Generate NCBI database submission xml
	xml_str = create_submission_xml(organism=organism, submission_name=submission_name, metadata=metadata, config_dict=config_dict)
	file_handler.save_xml(submission_xml=xml_str, submission_dir=submission_dir)

